+
+    private submit = (): void => {
+        if (this.props.busy || !this.state.token) return;
+
+        this.props.submitAuthDict({ type: this.props.loginType, token: this.state.token });
+    };
+
+    private onSubmit = (e: FormEvent): void => {
+        e.preventDefault();
